#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_invertMode;
uniform float amzp_amount;
uniform float amzp_threshold;
uniform float amzp_brightness;
uniform float amzp_contrast;
uniform float amzp_saturation;
uniform float amzp_blend;




        float3 saturateCol(float3 col, float sat) {
            float grey = dot(col, float3(0.2126, 0.7152, 0.0722));
            return mix(float3(grey), col, sat);
        }

        float3 applyContrast(float3 col, float con) {
            return (col - 0.5) * con + 0.5;
        }

        float getLuma(float3 col) {
            return dot(col, float3(0.2126, 0.7152, 0.0722));
        }


        float3 rgb2hsv(float3 c) {
            float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
            float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
            float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
            float d = q.x - min(q.w, q.y);
            float e = 1.0e-10;
            return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
        }


        float3 hsv2rgb(float3 c) {
            float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
            float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
            return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
        }

        void amzRender() {
            float2 uv = amzScreenNorm();

            float4 src = amzTexture(0, uv);
            float3 col = src.rgb;
            float alpha = src.a;

            float3 invertCol = col;

            if (int(amzp_invertMode) == 0) {

                invertCol = 1.0 - col;
            }
            else if (int(amzp_invertMode) == 1) {

                float luma = getLuma(col);

float invertLuma = 1.0 - luma;
                invertCol = col * (invertLuma / max(luma, 0.001));
            }
            else if (int(amzp_invertMode) == 2) {

                float3 hsv = rgb2hsv(col);
                hsv.x = fract(hsv.x + 0.5);
                invertCol = hsv2rgb(hsv);
            }
            else if (int(amzp_invertMode) == 3) {

                invertCol = float3(1.0 - col.r, col.g, col.b);
            }
            else if (int(amzp_invertMode) == 4) {

                invertCol = float3(col.r, 1.0 - col.g, col.b);
            }
            else if (int(amzp_invertMode) == 5) {

                invertCol = float3(col.r, col.g, 1.0 - col.b);
            }
            else if (int(amzp_invertMode) == 6) {

                invertCol = float3(1.0 - col.r, 1.0 - col.g, col.b);
            }
            else if (int(amzp_invertMode) == 7) {

                invertCol = float3(1.0 - col.r, col.g, 1.0 - col.b);
            }
            else if (int(amzp_invertMode) == 8) {

                invertCol = float3(col.r, 1.0 - col.g, 1.0 - col.b);
            }
            else if (int(amzp_invertMode) == 9) {

                float3 inv = 1.0 - col;
                float luma = getLuma(inv);
                invertCol = float3(luma);
            }
            else if (int(amzp_invertMode) == 10) {

                invertCol = pow(1.0 - col, float3(0.7));
            }
            else if (int(amzp_invertMode) == 11) {

                float luma = getLuma(col);
                float mask = 1.0 - smoothstep(0.0, amzp_threshold, luma);
                invertCol = mix(col, 1.0 - col, mask);
            }
            else if (int(amzp_invertMode) == 12) {

                float luma = getLuma(col);
                float mask = smoothstep(amzp_threshold, 1.0, luma);
                invertCol = mix(col, 1.0 - col, mask);
            }
            else if (int(amzp_invertMode) == 13) {

                float luma = getLuma(col);
                float lo = amzp_threshold * 0.5;
                float hi = amzp_threshold + (1.0 - amzp_threshold) * 0.5;
                float mask = smoothstep(lo, amzp_threshold, luma) * (1.0 - smoothstep(amzp_threshold, hi, luma));
                invertCol = mix(col, 1.0 - col, mask);
            }
            else if (int(amzp_invertMode) == 14) {

                invertCol = float3(1.0) - col * float3(0.95, 0.85, 0.75);
                invertCol = clamp(invertCol, 0.0, 1.0);
            }
            else if (int(amzp_invertMode) == 15) {

                float luma = getLuma(col);
                float mask = step(amzp_threshold, luma);
                invertCol = mix(col, 1.0 - col, mask);
            }


            float3 result = mix(col, invertCol, amzp_amount);


            result += amzp_brightness;
            result = applyContrast(result, amzp_contrast);
            result = saturateCol(result, amzp_saturation);
            result = clamp(result, 0.0, 1.0);

            amzOutput = float4(result, alpha) * amzp_blend + (1.0 - amzp_blend) * src;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

